solution.javascript:
function carFleet(target, position, speed) {
  const pairs = position.map((p, i) => [p, speed[i]]).sort((a, b) => b[0] - a[0]);
  const stack = [];
  for (const [pos, spd] of pairs) {
    const time = (target - pos) / spd;
    while (stack.length && time >= stack[stack.length - 1]) stack.pop();
    stack.push(time);
  }
  return stack.length;
}

solution.cpp:
int carFleet(int target, vector<int>& position, vector<int>& speed) {
    vector<pair<int,int>> pairs;
    for (int i = 0; i < position.size(); i++) pairs.push_back({position[i], speed[i]});
    sort(pairs.rbegin(), pairs.rend());
    stack<double> st;
    for (auto& [pos, spd] : pairs) {
        double time = (double)(target - pos) / spd;
        while (!st.empty() && time >= st.top()) st.pop();
        st.push(time);
    }
    return st.size();
}
